import urllib.request

def send_xml_payload(xml_body: str) -> str:
    req = urllib.request.Request('https://xml.old-gateway.internal/v1', data=xml_body.encode('utf-8'))
    return urllib.request.urlopen(req).read().decode('utf-8')

