def fetch_users_by_ids(conn, user_ids: list[int]) -> dict[int, dict]:
    cur = conn.cursor()
    cur.execute('SELECT id, email FROM users WHERE id = ANY(%s)', (user_ids,))
    return {row[0]: {'id': row[0], 'email': row[1]} for row in cur.fetchall()}

def fetch_single_user(conn, user_id: int) -> dict:
    cur = conn.cursor()
    cur.execute('SELECT id, email FROM users WHERE id = %s', (user_id,))
    row = cur.fetchone()
    return {'id': row[0], 'email': row[1]}
